LEVELS = ('open', 'personal', 'local')
LEVEL_LABELS = dict(open='Open', personal='Personal', local='Local only')
OVERRIDE_LEVEL = dict(clear='open', force='personal', local='local')
LEVEL_OVERRIDE = {v: k for k, v in OVERRIDE_LEVEL.items()}
TYPE_POLICY = {**{t: dict(preset='tables') for t in ('invoice', 'receipt', 'quote', 'catalogue')},
               **{t: dict(preset='generic') for t in ('paper', 'article')},
               **{t: dict(preset='generic', level='local', vision='local') for t in sorted(SENSITIVE)}}

def top(*ls) -> str:
    "The highest of some levels; `open` when none is given."
    return max((l for l in ls if l), key=LEVELS.index, default='open')

def _lvl(level):
    if level not in LEVELS: raise ValueError(f'unknown level {level!r}; one of {LEVELS}')
    return level

def _person(by, what):
    if by != 'person': raise PermissionError(f'only a person can {what}; {by} cannot')

def type_policy(doctype:str=None, text:str=None, kind:str=None) -> AttrDict:
    "What a type asks of a read: its preset, the level it starts at, and which vision models may read it."
    g = guess_type(text, kind=kind) if doctype is None and text else AttrDict(doctype=doctype)
    p = TYPE_POLICY.get(g.doctype) or {}
    # a guess raises the level when it is sure, or when a sensitive type scores well whatever the runner-up
    sure = doctype is not None or g.get('decisive') or (g.doctype in SENSITIVE and (g.get('score') or 0) >= MIN_SCORE)
    return AttrDict(doctype=g.doctype, score=g.get('score'), decisive=g.get('decisive'), sensitive=g.doctype in SENSITIVE,
                    preset=p.get('preset', 'generic'), level=p.get('level', 'open') if sure else 'open', vision=p.get('vision', 'any'))

@patch
def _privacy_t(self:Vault):
    t = self.db.t.vault_privacy
    if not t.exists():
        with write_txn(self.db): t.create(store=str, level=str, at=float, pk='store')
    return t

@patch
def floor(self:Vault) -> str:
    "The level no document on this shelf goes below: `open`, `personal` or `local`."
    t = self.db.t.vault_privacy
    return ((first(t.rows_where('store=?', [self.name])) or {}).get('level') if t.exists() else None) or 'open'

@patch
def set_floor(self:Vault, level:str='open', by:str='person') -> dict:
    "Set this shelf's floor. Only a person may lower it."
    if LEVELS.index(_lvl(level)) < LEVELS.index(self.floor()): _person(by, 'lower a floor')
    t = self._privacy_t()
    with write_txn(self.db): t.insert(dict(store=self.name, level=level, at=time.time()), replace=True)
    return dict(store=self.name, floor=level)

@patch
def _findings_t(self:Vault):
    t = self.db.t.pii_findings
    if not t.exists():
        with write_txn(self.db):
            t.create(id=str, doc_id=str, store=str, page=int, version=int, fp=str, kind=str, start=int, end=int, state=str, at=float, pk='id')
            self.db.execute('create index if not exists pii_findings_doc on pii_findings(store, doc_id, page)')
    return t

@patch
def _page_texts(self:Vault, doc_id:str) -> dict:
    "`{page: (text, version)}`: the latest read version of each page, else its chunks in order."
    if self.db.t.read_pages.exists():
        out = {r['page']: (r['text'] or '', r['version']) for r in self.db.t.read_pages.rows_where(
            'doc_id=? and store=?', [doc_id, self.name], order_by='page, version')}
        if out: return out
    out = {}
    for c in self.store(where='doc_id=?', where_args=[doc_id], select='content, page', order_by='rowid'):
        out.setdefault(c['page'] or 0, []).append(c['content'] or '')
    return {k: ('\n\n'.join(v), None) for k, v in out.items()}

def _spans(text, kind): return pii_spans(text, ner=kind != 'code')

@patch
def scan_pii(self:Vault, ref, pages=None) -> dict:
    "File each page's identifiers as findings: fingerprint, kind, offsets and page, never the value."
    d = self.doc(ref)
    if d is None: raise ValueError(f'no document in the vault matching {ref!r}')
    did, t, now, n = d['id'], self._findings_t(), time.time(), 0
    tx = {k: v for k, v in self._page_texts(did).items() if pages is None or k in set(pages)}
    keep = {r['fp']: r['state'] for r in t.rows_where("doc_id=? and store=? and state!='found'", [did, self.name])}
    with write_txn(self.db):
        for pg, (s, ver) in tx.items():
            self.db.execute('delete from pii_findings where doc_id=? and store=? and page=?', [did, self.name, pg])
            for a, b, k, v in _spans(s, d['kind']):
                f = fingerprint(k, v)
                t.insert(dict(id=uuid.uuid4().hex[:12], doc_id=did, store=self.name, page=pg, version=ver, fp=f, kind=k,
                              start=a, end=b, state=keep.get(f, 'found'), at=now))
                n += 1
    self.set_meta(did, pii_scanned=now)
    return dict(doc_id=did, pages=len(tx), findings=n)

@patch
def _found(self:Vault, d, page=None) -> L:
    "A document's findings, from the table once scanned, else counted in memory so a read path never writes."
    did = d['id']
    if d['meta'].get('pii_scanned'):
        w, a = 'doc_id=? and store=?', [did, self.name]
        if page is not None: w, a = w + ' and page=?', a + [page]
        return L(self._findings_t().rows_where(w, a))
    return L(dict(page=pg, kind=k, state='found') for pg, (s, _) in self._page_texts(did).items()
             if page is None or pg == page for _, _, k, _ in _spans(s, d['kind']))

@patch
def level(self:Vault, ref, page:int=None) -> AttrDict:
    "A document's privacy level: its mark, else what its type and findings say; never below the shelf's floor."
    d = self.doc(ref)
    if d is None: raise ValueError(f'no document in the vault matching {ref!r}')
    did, m = d['id'], d['meta']
    ov = (self.marks(did) or {}).get('pii_override')
    hit = lambda fs: Counter(f['kind'] for f in fs if f['state'] == 'accepted' or (f['state'] == 'found' and f['kind'] in IDENTIFYING))
    kinds = hit(self._found(d))
    if page is not None:
        txt = self._page_texts(did).get(page, ('', None))[0]
        # a page with no text to judge takes the whole document's verdict
        if txt.strip(): kinds = hit(self._found(d, page))
    det, tl, fl = 'personal' if kinds else 'open', (TYPE_POLICY.get(m.get('doctype')) or {}).get('level', 'open'), self.floor()
    lv = top(fl, OVERRIDE_LEVEL.get(ov) or top(tl, det))
    return AttrDict(doc_id=did, title=d['title'], page=page, level=lv, label=LEVEL_LABELS[lv], detected=det, override=ov,
                    floor=fl, doctype=m.get('doctype'), type_level=tl, kinds=dict(kinds))

@patch
def set_level(self:Vault, ref, level:str=None, reason:str='', by:str='person') -> dict:
    "Set a document's level by hand, or `None` to let detection decide again. Only a person may lower one or clear a mark."
    cur = self.level(ref)
    if level is None:
        if cur.override: _person(by, 'clear a mark')
        return dict(self.mark(ref, pii_override=None, pii_reason=None), privacy=self.level(ref))
    if LEVELS.index(_lvl(level)) < LEVELS.index(cur.level) or (cur.override and LEVELS.index(level) < LEVELS.index(OVERRIDE_LEVEL[cur.override])):
        _person(by, 'lower a level')
    return dict(self.mark(ref, pii_override=LEVEL_OVERRIDE[level], pii_reason=reason or None), privacy=self.level(ref))

@patch
def findings(self:Vault, ref=None, state:str=None, page:int=None) -> L:
    "Filed identifiers, each with a masked `preview` read off the current page text; never the value."
    w, a = ['store=?'], [self.name]
    if ref is not None:
        d = self.doc(ref)
        if d is None: raise ValueError(f'no document in the vault matching {ref!r}')
        w.append('doc_id=?'); a.append(d['id'])
    if state: w.append('state=?'); a.append(state)
    if page is not None: w.append('page=?'); a.append(page)
    tx = {}
    def prev(r):
        s = tx.setdefault(r['doc_id'], self._page_texts(r['doc_id'])).get(r['page'], ('', None))[0][r['start']:r['end']]
        return mask_preview(s, r['kind']) if s and fingerprint(r['kind'], s) == r['fp'] else None
    return L(self._findings_t().rows_where(' and '.join(w), a, order_by='doc_id, page, start')).map(lambda r: AttrDict(r, preview=prev(r)))

@patch
def _judge(self:Vault, ref, ids, state):
    d = self.doc(ref)
    if d is None: raise ValueError(f'no document in the vault matching {ref!r}')
    ids = [i for i in (ids.split(',') if isinstance(ids, str) else ids) if i]
    rows = {r['id']: r for r in self._findings_t().rows_where('doc_id=? and store=?', [d['id'], self.name])}
    if gone := [i for i in ids if i not in rows]:
        return dict(ok=False, kind='stale', ids=gone, error='these findings are gone: the page was read again')
    fps = list({rows[i]['fp'] for i in ids})
    with write_txn(self.db):
        self.db.execute(f"update pii_findings set state=? where doc_id=? and store=? and fp in ({','.join('?' * len(fps))})",
                        [state, d['id'], self.name, *fps])
    return dict(ok=True, privacy=self.level(d['id']))

@patch
def accept_pii(self:Vault, ref, ids, by:str='person') -> dict:
    "Say findings are personal. Every occurrence of the same value in the document follows."
    return self._judge(ref, ids, 'accepted')

@patch
def reject_pii(self:Vault, ref, ids, by:str='person') -> dict:
    "Say findings are not personal. Only a person may; the verdict survives a re-read, by fingerprint."
    _person(by, 'clear a finding')
    return self._judge(ref, ids, 'rejected')

@patch
def reset_pii(self:Vault, ref, ids, by:str='person') -> dict:
    "Take a verdict on findings back: every occurrence of the value is `found` again, for detection to judge. Only a person may."
    _person(by, 'clear a finding')
    return self._judge(ref, ids, 'found')

